`app/welcome/page.tsx`:

```tsx
import { after } from 'next/server'

export default async function WelcomePage() {
  after(async () => {
    try {
      await fetch('https://analytics.example.com/log', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ event: 'page_view', page: '/welcome' }),
      })
    } catch (e) {
      console.error('Analytics logging failed', e)
    }
  })

  return <h1>Welcome!</h1>
}
```

Use `after` from `next/server` to schedule the analytics call after the response is sent so rendering isn’t blocked. On older Next.js versions, import `unstable_after` instead.
